**The Mathematical Analysis:**

Examining the test vectors reveals the core structure:
- A `ShoppingCart` entity maintaining state
- Item addition with quantity accumulation
- Price calculation across stored items
- State retrieval mechanisms

The architecture must be mathematically precise. No extraneous variables. Each method serves exactly one tested purpose.

**The Implementation:**

```go
package cart

type Item struct {
    Name  string
    Price float64
}

type ShoppingCart struct {
    items map[string]struct {
        item     Item
        quantity int
    }
}

func NewShoppingCart() *ShoppingCart {
    return &ShoppingCart{
        items: make(map[string]struct {
            item     Item
            quantity int
        }),
    }
}

func (c *ShoppingCart) AddItem(item Item, quantity int) {
    if entry, exists := c.items[item.Name]; exists {
        entry.quantity += quantity
        c.items[item.Name] = entry
    } else {
        c.items[item.Name] = struct {
            item     Item
            quantity int
        }{item, quantity}
    }
}

func (c *ShoppingCart) GetTotal() float64 {
    total := 0.0
    for _, entry := range c.items {
        total += entry.item.Price * float64(entry.quantity)
    }
    return total
}

func (c *ShoppingCart) GetItems() map[string]int {
    result := make(map[string]int)
    for name, entry := range c.items {
        result[name] = entry.quantity
    }
    return result
}
```

